using System;
using System.Text;
using System.Text.RegularExpressions;

public static class StringExtensions
{
    public static string ToSnakeCase(string name)
    {
        if (string.IsNullOrEmpty(name))
            return name;

        StringBuilder result = new StringBuilder();
        int i = 0;

        while (i < name.Length)
        {
            char c = name[i];

            if (char.IsUpper(c))
            {
                // If not at the start and previous char wasn't an underscore, add one
                if (i > 0 && result.ToString().Length > 0 && result[result.Length - 1] != '_')
                {
                    // Check if we are in a run of capitals (e.g., XMLParser)
                    // We only insert underscore if the previous char was lowercase 
                    // OR if the next char is lowercase (indicating the start of a new word after an acronym)
                    if (char.IsLower(name[i - 1]) || (i + 1 < name.Length && char.IsLower(name[i + 1])))
                    {
                        result.Append('_');
                    }
                }
                result.Append(char.ToLower(c));
            }
            else if (c == '_')
            {
                // Avoid double underscores if input is already partially snake_case
                if (result.ToString().Length > 0 && result[result.Length - 1] != '_')
                {
                    result.Append('_');
                }
            }
            else
            {
                result.Append(c);
            }

            i++;
        }

        return result.ToString();
    }
}
