function Get-ExtensionCount {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string[]]$Path
    )

    $counts = @{}

    foreach ($item in $Path) {
        try {
            # Use System.IO.Path for performance and reliability over Get-Item/Get-ChildItem
            $ext = [System.IO.Path]::GetExtension($item).ToLower()

            # Remove the leading dot if it exists
            if ($ext.StartsWith('.')) {
                $ext = $ext.Substring(1)
            }

            $counts[$ext]++
        }
        catch {
            # Handle potential invalid path characters/errors by treating as empty extension or skipping
            $counts[""]++
        }
    }

    return $counts
}
