function Split-Chunk {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [object[]]$Items,

        [Parameter(Mandatory = $true)]
        [int]$Size
    )

    process {
        if ($Size -le 0) {
            throw "Size must be greater than zero."
        }

        for ($i = 0; $i -lt $Items.Count; $i += $Size) {
            $end = [Math]::Min($i + $Size, $Items.Count)
            # Using the comma operator to prevent PowerShell from flattening the array into the pipeline
            ,($Items[$i..($end - 1)])
        }
    }
}
