function ConvertFrom-KeyValue {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Text
    )

    $hashTable = @{}

    if ([string]::IsNullOrWhiteSpace($Text)) {
        return $hashTable
    }

    # Split by semicolon to get pairs
    $pairs = $Text -split ';'

    foreach ($pair in $pairs) {
        # Skip empty or whitespace-only segments
        if ([string]::IsNullOrWhiteSpace($pair)) {
            continue
        }

        # Find the index of the first '=' to handle values containing '=' correctly
        $index = $pair.IndexOf('=')

        if ($index -ge 0) {
            $key = $pair.Substring(0, $index).Trim()
            $value = $pair.Substring($index + 1).Trim()

            # Only add if key is not empty after trimming
            if (-not [string]::IsNullOrWhiteSpace($key)) {
                $hashTable[$key] = $value
            }
        }
    }

    return $hashTable
}
