function Get-Fibonacci {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [int]$Count
    )

    if ($Count -le 0) { return }

    $sequence = New-Object System.Collections.Generic.List[long]

    for ($i = 0; $i -lt $Count; $i++) {
        if ($i -eq 0) {
            $sequence.Add(0L)
        }
        elseif ($i -eq 1) {
            $sequence.Add(1L)
        }
        else {
            $next = $sequence[$i - 1] + $sequence[$i - 2]
            $sequence.Add($next)
        }
    }

    return $sequence
}
