function Get-WeekdayCount {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [datetime]$Start,

        [Parameter(Mandatory = $true)]
        [datetime]$End
    )

    if ($End -lt $Start.Date) {
        return 0
    }

    # Normalize to start of day to ensure consistent iteration
    $current = $Start.Date
    $end = $End.Date
    $count = 0

    while ($current -le $end) {
        # DayOfWeek: 1=Monday, 5=Friday
        if ($current.DayOfWeek -ge 1 -and $current.DayOfWeek -le 5) {
            $count++
        }
        $current = $current.AddDays(1)
    }

    return $count
}
